// Nhớ khoá của dòng cuối, không nhớ số trang
OffsetDateTime lastCreatedAt = periodStart;          // mốc đầu kỳ xuất; id luôn > 0
long lastId = 0;
OffsetDateTime cutoff = periodEnd;                   // mốc chốt sổ: đơn tạo sau mốc này vào kỳ sau
List<OrderRow> rows;
do {
    rows = jdbcClient.sql("""
            SELECT id, customer_id, total, created_at
            FROM orders
            WHERE status = 'PAID'
              AND created_at < :cutoff
              AND (created_at, id) > (:lastCreatedAt, :lastId)
            ORDER BY created_at, id
            LIMIT 1000""")
        .param("cutoff", cutoff)
        .param("lastCreatedAt", lastCreatedAt)
        .param("lastId", lastId)
        .query(OrderRow.class)
        .list();
    writer.write(rows);
    if (!rows.isEmpty()) {
        OrderRow last = rows.getLast();          // Java 21
        lastCreatedAt = last.createdAt();
        lastId = last.id();
    }
} while (!rows.isEmpty());
